import javafx.geometry.*;import java.util.*;import ru.bccontrol.sedonastudio.ui.WireRouter;
public class WireRouterTests {
 static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
 static boolean hits(Point2D a,Point2D b,Bounds box){if(a.getY()==b.getY())return a.getY()>box.getMinY()&&a.getY()<box.getMaxY()&&Math.max(a.getX(),b.getX())>box.getMinX()&&Math.min(a.getX(),b.getX())<box.getMaxX();return a.getX()>box.getMinX()&&a.getX()<box.getMaxX()&&Math.max(a.getY(),b.getY())>box.getMinY()&&Math.min(a.getY(),b.getY())<box.getMaxY();}
 static void valid(List<Point2D> route,Point2D from,Point2D to,Bounds source,Bounds target,List<Bounds> obstacles){check(route.size()>=2,"Missing route");check(route.get(0).equals(from)&&route.get(route.size()-1).equals(to),"Exact ends");check(route.get(1).getY()==from.getY()&&route.get(1).getX()>=from.getX(),"Horizontal source exit");check(route.get(route.size()-2).getY()==to.getY()&&route.get(route.size()-2).getX()<=to.getX(),"Horizontal target entry");for(int i=1;i<route.size();i++){Point2D a=route.get(i-1),b=route.get(i);check(a.getX()==b.getX()||a.getY()==b.getY(),"Nonorthogonal segment");for(Bounds box:obstacles)if(!(i==1&&box==source)&&!(i==route.size()-1&&box==target))check(!hits(a,b,box),"Route crosses a card: "+box);}}
 public static void main(String[] args){
  List<Bounds> boxes=new ArrayList<>();for(int i=0;i<100;i++){boxes.add(new BoundingBox(60,60+i*72,220,48));boxes.add(new BoundingBox(720,60+i*72,220,48));}WireRouter router=new WireRouter(boxes,1200,7600);long start=System.nanoTime();for(int i=0;i<100;i++){Bounds a=boxes.get(i*2),b=boxes.get(i*2+1);Point2D from=new Point2D(a.getMaxX()-12,a.getMinY()+24.25),to=new Point2D(b.getMinX()+12,b.getMinY()+24.25);valid(router.route(from,to,a,b),from,to,a,b,boxes);}check(router.statistics().simpleRoutes()==100&&router.statistics().searches()==0,"Empty corridors should skip search");System.out.println("PASS corridor workload: 200 cards / 100 links, "+((System.nanoTime()-start)/1_000_000)+" ms; no A* search");
  Bounds a=new BoundingBox(60,60,220,200),b=new BoundingBox(700,300,220,200),block=new BoundingBox(350,80,260,500);List<Bounds> blocked=List.of(a,b,block);router=new WireRouter(blocked,1200,800);Point2D from=new Point2D(268,120.25),to=new Point2D(712,360.25);valid(router.route(from,to,a,b),from,to,a,b,blocked);check(router.statistics().searches()==1,"Obstacle must use fallback");
  Bounds self=new BoundingBox(120,120,220,220);router=new WireRouter(List.of(self),900,700);from=new Point2D(328,180.25);to=new Point2D(132,240.25);valid(router.route(from,to,self,self),from,to,self,self,List.of(self));check(router.statistics().searches()==1,"Self link must use fallback");
  a=new BoundingBox(60,60,220,160);b=new BoundingBox(700,60,220,160);router=new WireRouter(List.of(a,b),1200,600);from=new Point2D(268,120.25);to=new Point2D(712,180.25);for(int i=0;i<4;i++)valid(router.route(from,to,a,b),from,to,a,b,List.of(a,b));check(router.statistics().searches()>0,"Occupied corridors must retain traffic-aware search");
  Bounds wall=new BoundingBox(400,0,180,600);router=new WireRouter(List.of(a,b,wall),1200,600);check(router.route(from,to,a,b).isEmpty(),"Blocked wall must not produce a crossing");
  Random random=new Random(20261113L);int found=0;long simple=0,searched=0;
  for(int scene=0;scene<200;scene++){Bounds left=new BoundingBox(60,60,220,180),right=new BoundingBox(900,360,220,180);List<Bounds> obstacles=new ArrayList<>(List.of(left,right));for(int i=0;i<5;i++)obstacles.add(new BoundingBox(360+random.nextInt(34)*12,24+random.nextInt(48)*12,48+random.nextInt(5)*12,48+random.nextInt(10)*12));WireRouter candidate=new WireRouter(obstacles,1400,900);Point2D output=new Point2D(268,144.25),input=new Point2D(912,444.25);List<Point2D> route=candidate.route(output,input,left,right);if(!route.isEmpty()){valid(route,output,input,left,right,obstacles);found++;}simple+=candidate.statistics().simpleRoutes();searched+=candidate.statistics().searches();}
  check(found>150&&simple>0&&searched>0,"Seeded obstacle scenes must exercise both algorithms");System.out.println("PASS 200 seeded obstacle scenes: "+found+" routes checked, simple="+simple+", search="+searched);
  System.out.println("PASS routing: exact off-grid port leads, orthogonal clear corridors, obstacle fallback, self link, occupied lanes and impenetrable wall");
 }
}
